PANTHEON_BETA_CATEGORIES = {
    "ecology": {"name": "Ecology & Biology", "agents": ECOLOGY_AGENTS, "color": "#16A34A"},
    "geography": {"name": "Geography & Cartography", "agents": GEOGRAPHY_AGENTS, "color": "#78716C"},
    "sociology": {"name": "Sociology & Anthropology", "agents": SOCIOLOGY_AGENTS, "color": "#7C3AED"},
    "engineering": {"name": "Engineering & Technology", "agents": ENGINEERING_AGENTS, "color": "#6B7280"},
}

def get_all_pantheon_beta_agents() -> list:
    agents = []
    for cat_id, cat in PANTHEON_BETA_CATEGORIES.items():
        for agent in cat["agents"]:
            agents.append({"id": agent["id"], "name": agent["name"], "role": agent["role"], "specialty": agent["specialty"], "color": agent["color"], "category": cat_id, "category_name": cat["name"]})
    return agents

def get_pantheon_beta_prompt(agent_id: str, context: str) -> tuple:
    for cat_id, cat in PANTHEON_BETA_CATEGORIES.items():
        for agent in cat["agents"]:
            if agent["id"] == agent_id:
                return (f"{agent['persona']}\n\nYou are part of the Expert Pantheon (Beta Division). Apply your deep domain expertise to enhance game development.", f"As {agent['name']} ({agent['role']}), apply your expertise to:\n\n{context}")
    return ("You are a domain expert.", f"Analyze: {context}")
